frappe.example:
frappe.call({
    method: "my_app.api.get_employee_details",
    args: { employee_id: "EMP-001" },
    freeze: true,
    callback: function(r) {
        console.log(r.message);
    }
});

frappe.prompt([
    { fieldname: "reason", fieldtype: "Small Text", label: __("Reason"), reqd: 1 }
], function(values) {
    console.log(values.reason);
}, __("Enter Reason"));

frappe.web_form.example:
frappe.web_form.on("onload", () => {
    frappe.web_form.set_value("posting_date", frappe.datetime.nowdate());
});
frappe.web_form.on("department", (field, val) => {
    console.log("Department changed to:", val);
});

frappe.model.example:
frappe.ui.form.on("Sales Order Item", {
    qty(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        // Calculate amount and update field with trigger:
        const total_amount = row.qty * row.rate;
        frappe.model.set_value(cdt, cdn, "amount", total_amount);
    }
});

frappe.realtime.example:
// Listen for real-time task completion broadcast from backend worker:
frappe.realtime.on("import_progress", function(data) {
    frappe.show_progress(__("Importing Customers"), data.current, data.total, data.message);
    if (data.current === data.total) {
        frappe.show_alert({ message: __("Import Finished!"), indicator: "green" });
        cur_frm.reload_doc();
    }
});

frappe.ui.form.example:
// 1. Parent DocType handlers:
frappe.ui.form.on("Customer", {
    refresh(frm) {
        if (frm.is_new()) {
            frm.set_intro(__("Please fill all required business registration details."), "blue");
        }
    },
    customer_type(frm) {
        frm.toggle_reqd("tax_id", frm.doc.customer_type === "Company");
    }
});

// 2. Child Table handlers:
frappe.ui.form.on("Sales Order Item", {
    items_add(frm, cdt, cdn) {
        frappe.msgprint(__("New item row added!"));
    },
    rate(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        frappe.model.set_value(cdt, cdn, "amount", row.qty * row.rate);
    }
});
